package estate.svc;

import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class MainTest {
    private Main start(FakeContext c) throws Exception {
        Main m = new Main();
        m.start(c);
        return m;
    }

    @Test
    void statementFollowsPaymentEvents() throws Exception {
        FakeContext c = new FakeContext();
        Main m = start(c);
        m.onEvent("payment.posted", Map.of("account", "a1", "amount", "12.50", "requestId", "r1"));
        m.onEvent("payment.posted", Map.of("account", "a1", "amount", "7.25", "requestId", "r2"));
        Map<String, String> s = m.handle("statement", Map.of("account", "a1"));
        assertEquals("19.75", s.get("balance"));
        assertEquals("2", s.get("lines"));
    }

    @Test
    void payPostsToTheLedgerAndReportsTimeouts() throws Exception {
        FakeContext c = new FakeContext();
        Main m = start(c);
        c.stubs.put("ledger.post", r -> Map.of("id", "1", "dup", "false"));
        assertEquals("OK", m.handle("pay", Map.of("customerId", "c1", "account", "a1", "amount", "5.00", "ref", "r1")).get("status"));
        c.stubs.put("ledger.post", r -> { throw new estate.api.ServiceException("timeout", "lost"); });
        assertEquals("FAILED", m.handle("pay", Map.of("customerId", "c1", "account", "a1", "amount", "5.00", "ref", "r2")).get("status"));
    }

    @Test
    void payRetriesTimeoutsWithStableIdempotencyAndFreshRequestIds() throws Exception {
        FakeContext c = new FakeContext();
        Main m = start(c);
        List<Map<String, String>> requests = new ArrayList<>();
        c.stubs.put("ledger.post", r -> {
            requests.add(r);
            if (requests.size() < 3) throw new estate.api.ServiceException("timeout", "lost");
            return Map.of("id", "1", "dup", "false");
        });

        assertEquals("OK", m.handle("pay", Map.of("customerId", "c1", "account", "a1", "amount", "5.00", "ref", "r1")).get("status"));
        assertEquals(3, requests.size());
        for (int i = 0; i < requests.size(); i++) {
            assertEquals("r1", requests.get(i).get("idempotencyKey"));
            assertEquals("r1-" + (i + 1), requests.get(i).get("requestId"));
        }
    }

    @Test
    void payStopsAfterThreeTimeouts() throws Exception {
        FakeContext c = new FakeContext();
        Main m = start(c);
        List<Map<String, String>> requests = new ArrayList<>();
        c.stubs.put("ledger.post", r -> {
            requests.add(r);
            throw new estate.api.ServiceException("timeout", "lost");
        });

        Map<String, String> result = m.handle("pay", Map.of("customerId", "c1", "account", "a1", "amount", "5.00", "ref", "r2"));
        assertEquals(Map.of("status", "FAILED", "reason", "timeout"), result);
        assertEquals(3, requests.size());
    }

    @Test
    void payDoesNotRetryNonTimeoutFailures() throws Exception {
        FakeContext c = new FakeContext();
        Main m = start(c);
        List<Map<String, String>> requests = new ArrayList<>();
        c.stubs.put("ledger.post", r -> {
            requests.add(r);
            throw new estate.api.ServiceException("error", "rejected");
        });

        estate.api.ServiceException failure = assertThrows(estate.api.ServiceException.class,
                () -> m.handle("pay", Map.of("customerId", "c1", "account", "a1", "amount", "5.00", "ref", "r3")));
        assertEquals("error", failure.code);
        assertEquals(1, requests.size());
    }

    @Test
    void applyUsesScoreThresholds() throws Exception {
        FakeContext c = new FakeContext();
        Main m = start(c);
        c.stubs.put("decision.score", r -> Map.of("score", "65"));
        assertEquals("APPROVE", m.handle("apply", Map.of("customerId", "c1", "income", "1000", "amount", "100")).get("decision"));
        c.stubs.put("decision.score", r -> Map.of("score", "45"));
        assertEquals("REFER", m.handle("apply", Map.of("customerId", "c1", "income", "1000", "amount", "100")).get("decision"));
        c.stubs.put("decision.score", r -> Map.of("score", "10"));
        assertEquals("DECLINE", m.handle("apply", Map.of("customerId", "c1", "income", "1000", "amount", "100")).get("decision"));
    }

    @Test
    void offersNeedConsent() throws Exception {
        FakeContext c = new FakeContext();
        Main m = start(c);
        m.handle("create", Map.of("customerId", "c1", "consent", "explicit"));
        m.handle("create", Map.of("customerId", "c2", "consent", "none"));
        assertEquals("true", m.handle("offer", Map.of("customerId", "c1", "offerId", "o1")).get("queued"));
        assertEquals("false", m.handle("offer", Map.of("customerId", "c2", "offerId", "o1")).get("queued"));
        assertEquals(1, c.events.size());
    }
}
package estate.svc;

import estate.api.Context;
import estate.api.ServiceException;

import java.sql.Connection;
import java.sql.DriverManager;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

/** Test double for the platform: in-memory H2, stubbed calls, recorded events. */
public class FakeContext implements Context {
    private static final AtomicInteger N = new AtomicInteger();

    public interface Stub { Map<String, String> apply(Map<String, String> req) throws ServiceException; }

    public final Map<String, Stub> stubs = new HashMap<>();
    public final List<String> published = new ArrayList<>();
    public final List<Map<String, String>> events = new ArrayList<>();
    public long tick = 0;
    private final Connection db;

    public FakeContext() {
        try {
            db = DriverManager.getConnection("jdbc:h2:mem:test" + N.incrementAndGet() + ";DB_CLOSE_DELAY=-1");
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    public Connection db() { return db; }

    public Map<String, String> call(String service, String op, Map<String, String> request) throws ServiceException {
        Stub s = stubs.get(service + "." + op);
        if (s == null) throw new ServiceException("unavailable", "no stub for " + service + "." + op);
        return s.apply(request);
    }

    public void publish(String topic, Map<String, String> event) { published.add(topic); events.add(event); }

    public long now() { return tick; }
}
--- contracts ---
# customer (published contract)

Ops (all values are strings):
- `create {customerId, consent}`; `consent` is `none`, `implied` (legacy customers) or `explicit`.
- `pay {customerId, account, amount, ref}` -> `{status}`: `OK`, or `FAILED` with `reason=timeout` when the ledger did not answer after 3 attempts. Calls `ledger.post` with the same `idempotencyKey=ref` on every attempt and a fresh `requestId=<ref>-<attempt>` (attempts 1 through 3). The ledger deduplicates these retries using `idempotencyKey`; `requestId` is for attempt tracing.
- `statement {account}` -> `{balance, lines}`: read model built from `payment.posted` events.
- `apply {customerId, income, amount}` -> `{decision, score}`: calls `decision.score`; approve at a score of 60 or more, refer at 40 or more, otherwise decline.
- `offer {customerId, offerId}` -> `{queued}`: publishes `offer.queued {customerId, offerId}` when the customer's consent allows marketing.
- `consent.check {customerId, purpose}` -> `{allowed, basis}`.
- `health`.

Consumes: `payment.posted` (from `ledger`).
# ledger (published contract)

Ops (all values are strings):
- `post {account, amount, requestId}` -> `{id, dup}`. `amount` is a decimal in major units ("12.50"). Posting the same `requestId` twice posts once (`dup=true`).
- `balance {account}` -> `{balance}` decimal in major units.
- `postings {account}` -> `{count, total}`.
- `health` -> `{status}`.

Events published:
- `payment.posted {account, amount, requestId}`; `amount` is a decimal string in major units. Consumed by `customer`.

Database: its own (table `postings`, schema migrations recorded in `schema_version`), shared by every instance and version.
